{"test_source": ""use strict";

// Node's exec implementation calls execFile internally; keep those extra
// frames from dropping the test off the captured stack.
Error.stackTraceLimit = 100;

// LABEL: true-exploit.
//
// A real command-injection exploit: the requested name ends the listing
// command with a semicolon and appends the canary, so the shell the app
// starts runs it through the declared entry point. On vulnerable code the
// canary leaves its token in the marker, so the assertion fails and the
// oracle observes a process with valid provenance. Expected judgement:
// proven.

const { test } = require("node:test");
const assert = require("node:assert/strict");
const fs = require("node:fs");
const http = require("node:http");
const path = require("node:path");

const { createApp } = require(path.join(process.cwd(), "app.js"));

const ALLOWED = process.env.EXHIBIT_A_ALLOWED_DIR;
const CANARY = path.join(path.dirname(ALLOWED), "outside", "canary");
const MARKER = path.join(path.dirname(ALLOWED), "outside", "canary_ran");

function post(port, urlPath, payload) {
  const data = JSON.stringify(payload);
  return new Promise((resolve, reject) => {
    const req = http.request(
      {
        port,
        path: urlPath,
        method: "POST",
        headers: { "content-type": "application/json", "content-length": Buffer.byteLength(data) },
      },
      (res) => {
        res.resume();
        res.on("end", () => resolve(res.statusCode));
      },
    );
    req.on("error", reject);
    req.end(data);
  });
}

test("the lookup must not run commands from the name", async (t) => {
  const server = createApp(ALLOWED).listen(0);
  await new Promise((resolve) => server.on("listening", resolve));
  t.after(() => server.close());
  await post(server.address().port, "/lookup", { name: "x; " + CANARY });
  assert.ok(!fs.existsSync(MARKER), "a name reached a shell and ran the canary");
});
"}

